<?php namespace App\Services; use App\Models\AuditLog; use Illuminate\Http\Request; class AuditService { public function log(?Request $request,string $action,$subject=null,array $metadata=[]): void { AuditLog::create(['user_id'=>$request?->user()?->id,'action'=>$action,'subject_type'=>$subject?get_class($subject):null,'subject_id'=>$subject?->id,'ip_address'=>$request?->ip(),'user_agent'=>$request?->userAgent(),'metadata'=>$metadata]); } }